{"implementation": "def solve(case):
    # Validate
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    if 'text' not in case or 'passes' not in case or 'max_rounds' not in case:
        raise ValueError("missing required fields")
    text = case['text']
    passes = case['passes']
    max_rounds = case['max_rounds']
    if not isinstance(text, str):
        raise ValueError("text must be string")
    if not isinstance(passes, list):
        raise ValueError("passes must be list")
    if not isinstance(max_rounds, int):
        raise ValueError("max_rounds must be int")
    for p in passes:
        if not isinstance(p, dict):
            raise ValueError("pass must be dict")
        if 'name' not in p or 'old' not in p or 'new' not in p:
            raise ValueError("pass missing name/old/new")
        if not isinstance(p['name'], str) or not isinstance(p['old'], str) or not isinstance(p['new'], str):
            raise ValueError("pass fields must be strings")
    current_text = text
    applications = []
    for _ in range(max_rounds):
        changed = False
        for p in passes:
            name = p['name']
            old = p['old']
            new = p['new']
            idx = current_text.find(old)
            if idx != -1:
                current_text = current_text[:idx] + new + current_text[idx+len(old):]
                applications.append(name)
                changed = True
        if not changed:
            return {"applications": applications, "fixed_point": True, "text": current_text}
    return {"applications": applications, "fixed_point": False, "text": current_text}"}
